import com.twintrade.app.PaperExecutionDelay;import java.util.Random;
public class PaperExecutionDelayTest{static void check(boolean b,String why){if(!b)throw new AssertionError(why);}static final class Sequence extends Random{final int[] v;int i;Sequence(int...v){this.v=v;}@Override public int nextInt(int bound){int x=v[i++];if(x<0||x>=bound)throw new AssertionError("bad fixture");return x;}}public static void main(String[] args){check(PaperExecutionDelay.sample(new Sequence(0))==30000,"5% tail");check(PaperExecutionDelay.sample(new Sequence(1,0))==3000,"lower bound");check(PaperExecutionDelay.sample(new Sequence(19,7000))==10000,"upper bound");System.out.println("PASS: paper delay sampler has exact 3-10 second bounds and a 5% 30-second branch.");}}
